package cli

import (
	"context"
	"encoding/json"
	"errors"
	"os"
	"path/filepath"
	"time"

	"github.com/mich-murphy/memory/internal/publication"
	"github.com/mich-murphy/memory/internal/sessioncapture"
)

const fixtureArchive = "fixture-archive-v1"

// Fixture content is synthetic and stable. IDs/digests are generated by the real
// capture writer, not handwritten wire JSON. Absolute source paths are deliberately
// provenance, so exports from different roots need not have identical manifest hashes.
func runCaptureFixture(ctx context.Context, args []string, o IO) (code int, err error) {
	root, kind, err := fixtureFlags(args, o)
	if err != nil {
		return exitUsage, err
	}
	if err := os.Mkdir(root, 0o700); err != nil {
		return exitFailed, errors.New("fixture output must be a new directory")
	}
	policyDir := filepath.Join(root, "policy")
	sources := filepath.Join(root, "sources")
	if err := makeFixtureDirs(policyDir, sources); err != nil {
		return exitFailed, err
	}
	backend, err := captureFixtureBackend(ctx, root, kind)
	if err != nil {
		return exitFailed, err
	}
	if err := publication.WriteArchive(ctx, backend, publication.Archive{Contract: publication.Contract, ArchiveID: fixtureArchive}); err != nil {
		return exitFailed, err
	}
	spool := filepath.Join(root, "spool")
	q, err := sessioncapture.Open(ctx, spool, sessioncapture.Options{
		ArchiveID: fixtureArchive, MaxSpoolBytes: 16 << 20,
		CheckPolicy: capturePolicy(policyDir, spool),
		Now:         func() time.Time { return time.Unix(1_700_000_000, 0).UTC() },
	})
	if err != nil {
		return exitFailed, err
	}
	defer func() {
		err = errors.Join(err, closeFixtureQueue(q))
		if err != nil {
			code = exitFailed
		}
	}()
	main1 := "{\"type\":\"user\",\"uuid\":\"u1\",\"message\":{\"role\":\"user\",\"content\":\"Synthetic hello π\"}}\n"
	main2 := main1 + "{\"type\":\"assistant\",\"uuid\":\"a1\",\"message\":{\"role\":\"assistant\",\"content\":[{\"type\":\"text\",\"text\":\"Synthetic reply\"},{\"type\":\"tool_use\",\"id\":\"call1\",\"name\":\"test\",\"input\":{}}]}}\n"
	rewrite := "{\"type\":\"user\",\"uuid\":\"u1\",\"message\":{\"role\":\"user\",\"content\":\"Rewritten synthetic epoch\"}}\n" +
		"{\"type\":\"user\",\"uuid\":\"t1\",\"message\":{\"role\":\"user\",\"content\":[{\"type\":\"tool_result\",\"tool_use_id\":\"call1\",\"content\":\"Synthetic output\"}]}}\n" + "not-json\n{\"type\":"
	child := "{\"type\":\"assistant\",\"uuid\":\"child1\",\"message\":{\"role\":\"assistant\",\"content\":\"Synthetic child reply\"}}\n"
	type sourceStep struct{ source, role, body string }
	id := publication.Identity{ArchiveID: fixtureArchive, MachineID: "fixture-machine", Agent: "claude", SessionID: "root/session"}
	for _, step := range []sourceStep{{"main", "main", main1}, {"main", "main", main2}, {"child", "subagent", child}, {"main", "main", rewrite}} {
		path := filepath.Join(sources, step.source+".jsonl")
		if err := os.WriteFile(path, []byte(step.body), 0o600); err != nil {
			return exitFailed, err
		}
		if _, err := q.Capture(ctx, sessioncapture.Request{Identity: id, SourceID: step.source, Role: step.role, Path: path, ObservedAtNS: 1_700_000_000_000_000_000}); err != nil {
			return exitFailed, err
		}
	}
	if err := q.Deliver(ctx, backend, id); err != nil {
		return exitFailed, err
	}
	if kind == "sdk-fixture" {
		closeErr := q.Close()
		q = nil
		if err := finishSDKFixture(closeErr, sources, spool); err != nil {
			return exitFailed, err
		}
	}
	if _, err := publication.ExportSession(ctx, backend, id, filepath.Join(root, "export")); err != nil {
		return exitFailed, err
	}
	return writeFixtureExpectations(root, id, []string{main2, child, rewrite})
}

func writeFixtureExpectations(root string, id publication.Identity, bodies []string) (int, error) {
	expect := map[string]any{"identity": id, "retained_bodies": bodies, "roles": map[string]string{"main": "main", "child": "subagent"}}
	data, err := json.Marshal(expect)
	if err != nil {
		return exitFailed, err
	}
	return exitOK, os.WriteFile(filepath.Join(root, "expectations.json"), data, 0o600)
}

func makeFixtureDirs(policyDir, sources string) error {
	for _, dir := range []string{filepath.Join(policyDir, "exclusions"), sources} {
		if err := os.MkdirAll(dir, 0o700); err != nil {
			return err
		}
	}
	return nil
}

func closeFixtureQueue(q *sessioncapture.Queue) error {
	if q == nil {
		return nil
	}
	return q.Close()
}

func finishSDKFixture(closeErr error, sources, spool string) error {
	if closeErr != nil {
		return closeErr
	}
	// Remove only owned synthetic inputs before authoritative export.
	for _, dir := range []string{sources, spool} {
		if err := os.RemoveAll(dir); err != nil {
			return err
		}
	}
	return nil
}
